#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    // If no argument is provided, treat as empty string (palindrome)
    if (argc <= 1) {
        puts("PALINDROME");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);
    if (len > 1024) { // limit observed in the binary
        puts("TOO_LONG");
        return 0;
    }

    // Normalize: keep only alphanumeric characters, convert to lower case
    char norm[1025]; // enough for max length + null terminator
    size_t n = 0;
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (('0' <= c && c <= '9') ||
            ('A' <= c && c <= 'Z') ||
            ('a' <= c && c <= 'z')) {
            if ('A' <= c && c <= 'Z')
                c = c + ('a' - 'A'); // to lower case
            norm[n++] = (char)c;
        }
    }
    norm[n] = '\0';

    // Check palindrome on the normalized string
    int is_pal = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
